<script setup lang="ts">
import { onMounted, ref } from 'vue'
import Avatar from 'primevue/avatar'; import AvatarGroup from 'primevue/avatargroup'; import Button from 'primevue/button'; import Column from 'primevue/column'; import DataTable from 'primevue/datatable'; import Dialog from 'primevue/dialog'; import InputText from 'primevue/inputtext'; import Select from 'primevue/select'
import AsyncContent from '@/components/common/AsyncContent.vue'; import PageHeader from '@/components/common/PageHeader.vue'; import StatusBadge from '@/components/common/StatusBadge.vue'
import { useAsyncData } from '@/composables/useAsyncData'; import { getTeam } from '@/services/workspace'

const inviteOpen = ref(false)
const { data: members, loading, error, load } = useAsyncData(getTeam)
onMounted(load)
</script>

<template><PageHeader :title="$t('team.title')" :description="$t('team.description')"><template #actions><AvatarGroup><Avatar v-for="item in members?.slice(0,3)" :key="item.id" :label="item.initials" shape="circle" /></AvatarGroup><Button :label="$t('team.invite')" icon="pi pi-user-plus" @click="inviteOpen=true" /></template></PageHeader><AsyncContent :loading="loading" :error="error" :empty="!members?.length" @retry="load"><section class="workspace-panel"><div class="mb-4 flex flex-wrap gap-2"><span class="p-input-icon-left flex-1"><i class="pi pi-search" /><InputText class="w-full" :placeholder="$t('team.search')" /></span><Select :options="[$t('common.all'),$t('team.product'),$t('team.engineering')]" :placeholder="$t('team.filter')" /></div><DataTable :value="members" paginator :rows="8"><Column :header="$t('team.member')"><template #body="{data:item}"><div class="flex items-center gap-3"><Avatar :label="item.initials" shape="circle" /><strong>{{ $t(item.nameKey) }}</strong></div></template></Column><Column :header="$t('team.role')"><template #body="{data:item}">{{ $t(`roles.${item.role}`) }}</template></Column><Column :header="$t('team.group')"><template #body="{data:item}">{{ $t(item.teamKey) }}</template></Column><Column :header="$t('team.status')"><template #body="{data:item}"><StatusBadge :label="$t(`presence.${item.status}`)" :severity="item.status==='online'?'success':'secondary'" /></template></Column><Column field="joined" :header="$t('team.joined')" /></DataTable></section></AsyncContent><Dialog v-model:visible="inviteOpen" modal :header="$t('team.invite')" class="w-[440px] max-w-[90vw]"><div class="grid gap-4"><label class="form-field"><span>{{ $t('team.email') }}</span><InputText type="email" placeholder="name@company.com" /></label><label class="form-field"><span>{{ $t('team.role') }}</span><Select :options="[$t('roles.admin'),$t('roles.member')]" /></label></div><template #footer><Button :label="$t('common.cancel')" text @click="inviteOpen=false" /><Button :label="$t('team.sendInvite')" @click="inviteOpen=false" /></template></Dialog></template>
